    <script>(()=>{if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}});const toggle=document.getElementById('theme-toggle');const sync=()=>{const dark=document.documentElement.classList.contains('dark');if(toggle){toggle.innerHTML=`<i data-lucide="${dark?'sun':'moon'}" class="h-4 w-4"></i>`;if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}})}};toggle?.addEventListener('click',()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);document.documentElement.classList.toggle('light',!dark);try{localStorage.setItem('bumcash_theme',dark?'dark':'light')}catch(_){}sync()});sync();const key='bumcash_warga_sidebar_collapsed';let desktopSidebarCollapsed=false;try{desktopSidebarCollapsed=localStorage.getItem(key)==='true'}catch(_){}document.documentElement.classList.toggle('warga-sidebar-collapsed',desktopSidebarCollapsed);document.getElementById('warga-desktop-collapse')?.addEventListener('click',()=>{desktopSidebarCollapsed=!document.documentElement.classList.contains('warga-sidebar-collapsed');document.documentElement.classList.toggle('warga-sidebar-collapsed',desktopSidebarCollapsed);try{localStorage.setItem(key,String(desktopSidebarCollapsed))}catch(_){}});const drawer=document.getElementById('warga-mobile-drawer');let mobileSidebarOpen=false;const close=()=>{mobileSidebarOpen=false;drawer.classList.add('hidden');drawer.setAttribute('aria-hidden','true');document.body.classList.remove('overflow-hidden')};const open=()=>{if(innerWidth>=1024)return;drawer.removeAttribute('x-cloak');mobileSidebarOpen=true;drawer.classList.remove('hidden');drawer.setAttribute('aria-hidden','false');document.body.classList.add('overflow-hidden')};document.getElementById('warga-mobile-toggle')?.addEventListener('click',open);document.getElementById('warga-drawer-close')?.addEventListener('click',close);document.getElementById('warga-drawer-backdrop')?.addEventListener('click',close);drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});window.addEventListener('resize',()=>{if(innerWidth>=1024&&mobileSidebarOpen)close()});const fallback=()=>{if(window.Alpine)return;document.querySelectorAll('[data-dropdown-trigger]').forEach(trigger=>{const menu=document.getElementById(trigger.dataset.dropdownTrigger);if(!menu)return;menu.removeAttribute('x-cloak');menu.classList.add('hidden');trigger.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('hidden');trigger.setAttribute('aria-expanded',String(!menu.classList.contains('hidden')))});document.addEventListener('click',e=>{if(!trigger.parentElement.contains(e.target)){menu.classList.add('hidden');trigger.setAttribute('aria-expanded','false')}})})};document.addEventListener('DOMContentLoaded',fallback,{once:true})})();</script>
